388	async function allocateFreshVmid(conn: any): Promise<number> {
389	  const candidate = await conn.nextVmid();
390	  const archived = await archivedVmids(conn);
391	
392	  // Ids already in use, so skipping forward cannot land on a live VM. Read
393	  // cluster-wide (qemu + lxc); fall back to this node's qemu list.
394	  let taken = new Set<number>();
395	  try {
396	    const res: any[] = await conn.get("/cluster/resources", { type: "vm" });
397	    for (const r of res ?? []) if (Number.isInteger(r?.vmid)) taken.add(r.vmid);
398	  } catch {
399	    const vms: any[] = await conn.get(`/nodes/${conn.node}/qemu`);
400	    taken = new Set((vms ?? []).map((v: any) => Number(v?.vmid)).filter(Number.isInteger));
401	  }
402	
403	  const { vmid, skipped } = pickProvisionVmid({ candidate, takenVmids: taken, archivedVmids: archived });
404	  if (skipped.length > 0) {
405	    console.warn(
406	      `[worker] vmid ${skipped.join(", ")} skipped for provisioning — still holds backup archives ` +
407	        `from a previous server; allocated ${vmid} instead`
408	    );
409	  }
410	  return vmid;
411	}
