export async function backupRestore(job: Job): Promise<void> {
  const server = await loadServer(job.serverId!);
  if (SANDBOX) {
    // Simulate a successful restore — animate the bar 0→100 so staging shows it.
    const steps = [
      { pct: 8, step: "Stopping server" },
      { pct: 30, step: "Restoring archive… 25%" },
      { pct: 55, step: "Restoring archive… 55%" },
      { pct: 80, step: "Restoring archive… 85%" },
      { pct: 95, step: "Starting server" },
      { pct: 100, step: "Restore complete" },
    ];
    for (const s of steps) {
      await reportJobProgress(job.id, s.pct, s.step);
      await new Promise((r) => setTimeout(r, 500));
    }
    await notify(
      server.userId,
      `Backup restored on ${server.hostname}`,
      "Your server was restored from the selected backup (sandbox).",
      `/dashboard/servers/${server.id}`
    );
    return;
  }
  if (!server.vmid) throw new Error("restore: server has no VM");

  const payload = (job.payload ?? {}) as { volid?: string };
  const volid = payload.volid;
  if (!volid) throw new Error("restore: missing volid");

  // DATA SAFETY (critical): step 2 below runs `qmrestore --force` over the live
  // vmid. PVE calls destroy_vm first ("avoid zombie disks when restoring over an
  // existing VM"), and destroy_vm frees EVERY volume that vmid owns — including
  // detached `unusedN` entries, because it passes include_unused => 1. Restoring
  // an archive taken before a volume was attached would therefore wipe that
  // volume's data while the Volume row still bills for it.
  //
  // Matches the reinstall guard, and mirrors requestRestore()'s check so a job
  // queued before that check existed (or enqueued by any other path) still cannot
  // destroy data. Counting by serverId alone is deliberate — detaching keeps the
  // disk owned by this vmid, so DETACHED volumes are just as exposed as attached.
  const pinnedVolumes = await db.volume.findMany({ where: { serverId: server.id } });
  const realPinned = pinnedVolumes.filter(
    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
  );
  if (realPinned.length > 0) {
    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
    throw new Error(
      `Restore blocked to protect your data volume(s): ${names}. Restoring replaces every ` +
        `disk this server owns, which would destroy them permanently. Move or delete them first.`
    );
  }

  const { conn, row: nodeRow } = await nodeFor(server);
  const vmid = server.vmid;
  const wasRunning = server.status === "RUNNING";

  // 1) Stop the VM so the disk can be overwritten (ignore "already stopped").
  await reportJobProgress(job.id, 3, "Stopping server");
  try {
    const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
    await conn.waitForTask(stopUpid);
  } catch {
    /* already stopped / not running */
  }
  await db.server.update({ where: { id: server.id }, data: { status: "STOPPED" } });

  // 2) Restore the archive over the existing VMID (force overwrite). Storage is
  //    left to the archive's recorded config so disks land where they were.
  //    Task progress (0..100) is mapped into the 10..90 window of the bar.
  await reportJobProgress(job.id, 10, "Restoring archive…");
  const restoreUpid = await conn.post(`/nodes/${conn.node}/qemu`, {
    vmid,
    archive: volid,
    force: 1,
  });
  await waitForTaskProgress(
    conn,
    restoreUpid,
    (progress, step) => reportJobProgress(job.id, progress, step),
    { timeoutMs: 3_600_000, phase: "restore", base: 10, span: 80 }
  );

  // 3) Reassert the VM's identity from the `Server` row, BEFORE it is started.
  //    `qmrestore --force` replaced the whole config, so at this instant the VM
  //    holds the archive's network and size, not this account's. See
  //    lib/restore-identity.ts for what that costs if it is left alone.
  await reportJobProgress(job.id, 92, "Restoring network configuration");
  try {
    await reapplyIdentity(conn, nodeRow, server, vmid);
  } catch (e) {
    // Tell the customer, then fail the job. Both matter: the VM is deliberately
    // left powered off, which is not what they asked for and must not look like
    // a silent success.
    await notify(
      server.userId,
      `Restore incomplete on ${server.hostname}`,
      e instanceof RestoreIdentityError || e instanceof Error
        ? e.message
        : "The server's network configuration could not be restored; it has been left powered off.",
      `/dashboard/servers/${server.id}`,
    );
    throw e;
  }

  // 4) Bring the VM back up if it was running before the restore.
  if (wasRunning) {
    await reportJobProgress(job.id, 95, "Starting server");
    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
    await conn.waitForTask(startUpid);
    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
  }
  await reportJobProgress(job.id, 100, "Restore complete");

  await notify(
    server.userId,
    `Backup restored on ${server.hostname}`,
    "Your server was restored from the selected backup. Any changes made after that backup are gone.",
    `/dashboard/servers/${server.id}`
  );
}

