/**
 * Force the CURRENT (DB) root password onto a running guest via the QEMU guest
 * agent — no reboot, no dependence on cloud-init. Same primitive `passwordReset`
 * (worker/index.ts) uses to change a password live; pulled out here so any other
 * caller whose action replaces or reverts the VM's actual disk content can reuse
 * it, rather than re-deriving the QGA call.
 *
 * WHY THIS EXISTS BEYOND passwordReset: `SNAPSHOT_ROLLBACK` and `BACKUP_RESTORE`
 * both put an OLDER copy of the guest's real disk back — including whatever
 * `/etc/shadow` existed at snapshot/backup time — while `Server.rootPasswordEnc`
 * in the DB keeps whatever the CURRENT password is. If a `PASSWORD_RESET` (or
 * any other password change) happened between that snapshot/backup being taken
 * and it being rolled back to / restored from, the guest reverts to the OLDER
 * password while the DB still holds the NEWER one — every later SSH from the
 * platform (control panel, GAME_POWER, mods, backups) then authenticates with
 * the DB's password against a guest that has a different one, failing with "All
 * configured authentication methods failed". This is the identical divergence
 * class documented on `provision()`'s password-reuse fix, just reached by
 * reverting old disk state instead of a retried clone — see that comment for the
 * full incident. Callers must invoke this after the VM is confirmed running and
 * its guest agent has answered (e.g. via `waitForGuestAgent`).
 *
 * Best-effort: never throws. Returns whether the QGA call was accepted — false
 * means the guest's password could not be confirmed resynced, which callers
 * should log loudly rather than silently swallow (the rollback/restore itself
 * still genuinely succeeded, so this must not fail that job).
 */
export async function applyPasswordToGuest(conn: PveClient, vmid: number, password: string): Promise<boolean> {
  try {
    const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/agent/set-user-password`, {
      username: "root",
      password,
    });
    if (typeof upid === "string" && upid.startsWith("UPID")) await conn.waitForTask(upid);
    return true;
  } catch (e) {
    console.error(`[proxmox] applyPasswordToGuest failed for vmid ${vmid}`, e);
    return false;
  }
}

export async function listSnapshots(vmid: number): Promise<any[]> {
  const snaps = await pve.get(`/nodes/${NODE}/qemu/${vmid}/snapshot`);
  return snaps.filter((s: any) => s.name !== "current");
}

